from __future__ import annotations

from dataclasses import dataclass


FORBIDDEN_PRODUCT_LABELS = (
    "codex",
    "chatgpt",
    "openai",
    "ai-generated",
    "generated by",
    "agent",
    "auto-generated",
    "由 codex 生成",
    "ai生成",
)


@dataclass(frozen=True)
class TypeMimicSpec:
    product_key: str
    output_slug: str
    manual_review_items: tuple[str, ...]
    forbidden_claims_avoided: tuple[str, ...]
    reference_policy_notes: tuple[str, ...]

    def validate_neutral_output_slug(self) -> None:
        lowered = self.output_slug.casefold()
        hits = [label for label in FORBIDDEN_PRODUCT_LABELS if label in lowered]
        if hits:
            raise ValueError(f"Forbidden product label in output slug {self.output_slug!r}: {hits}")
